code='''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    # First detect horizontal bands: every row is uniform, with zero rows as gaps.
    rowvals=[]
    rowmode=True
    for row in grid:
        nz=[v for v in row if v]
        if len(set(nz))>1:
            rowmode=False; break
        rowvals.append(nz[0] if nz else None)
    if rowmode and any(x is None for x in rowvals):
        for p in range(1,h+1):
            known={}
            ok=True
            for i,v in enumerate(rowvals):
                if v is not None:
                    k=i%p
                    if k in known and known[k]!=v: ok=False; break
                    known[k]=v
            if ok and len(known)==p:
                seq=known
                return [[seq[r%p] for _ in range(w)] for r in range(h)]
    # Otherwise complete a pattern that is constant on diagonal classes.
    pts=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    if not pts: return [row[:] for row in grid]
    # Use the diagonal orientation with stronger support (many cells on same diagonal).
    def support(sign):
        counts=defaultdict(int)
        for r,c,v in pts: counts[(r + sign*c)] += 1
        return sum(n*n for n in counts.values())
    # sum invariant uses sign=+1, difference invariant uses sign=-1
    sign=1 if support(1)>support(-1) else -1
    best=None
    for p in range(1, min(h,w)+1):
        vals={}; ok=True
        for r,c,v in pts:
            k=(r+sign*c)%p
            if k in vals and vals[k]!=v:
                ok=False; break
            vals[k]=v
        if ok and len(vals)==p:
            best=(p,vals); break
    if best is None:
        # Pick the consistent period with greatest residue coverage.
        choices=[]
        for p in range(1,min(h,w)+1):
            vals={}; bad=0
            for r,c,v in pts:
                k=(r+sign*c)%p
                if k in vals and vals[k]!=v: bad+=1
                else: vals[k]=v
            choices.append((bad, -len(vals), p, vals))
        _,_,p,vals=min(choices,key=lambda x:(x[0],x[1],x[2]))
        # Fill missing template entries by nearest known residue.
        for k in range(p):
            if k not in vals:
                near=min(vals, key=lambda j:min((k-j)%p,(j-k)%p))
                vals[k]=vals[near]
        best=(p,vals)
    p, vals=best
    return [[vals[(r+sign*c)%p] for c in range(w)] for r in range(h)]
'''
